def max_aggregate(tuples):
    # Create a dictionary to store the aggregate of each name
    aggregate_dict = {}
    # Iterate over the list of tuples
    for name, value in tuples:
        # If the name is already in the dictionary, add the value to its current value
        if name in aggregate_dict:
            aggregate_dict[name] += value
        # If the name is not in the dictionary, add it with its value
        else:
            aggregate_dict[name] = value
    # Find the maximum value in the dictionary
    max_value = max(aggregate_dict.values())
    # Find the name(s) with the maximum value
    max_names = [name for name, value in aggregate_dict.items() if value == max_value]
    # If the maximum value is not unique, return the first name and the sum of all values
    if len(max_names) > 1:
        return (max_names[0], sum(aggregate_dict.values()))
    # Otherwise, return the name and the maximum value
    return (max_names[0], max_value)

