def dict_depth(d):
    """
    This function calculates the depth of a dictionary.

    It does this by counting the number of nested dictionaries.

    :param d: The dictionary to calculate the depth of.
    :return: The depth of the dictionary.
    """
    if not isinstance(d, dict):
        return 0
    else:
        if not d:
            return 0
        else:
            depths = []
            for k, v in d.items():
                if isinstance(v, dict):
                    depths.append(dict_depth(v) + 1)
            if not depths:
                return 1
            else:
                return max(depths)

